    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint addAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (addAmount)); require(addAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= addAmount);
        uint balStart = address(this).balance;

        c.addToBalance{value: addAmount}(); if (__ESBMC_reverted()) return;

        uint userBalBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint balEnd = address(this).balance;

        assert(balEnd + addAmount == balStart + (withdrawReverted ? 0 : userBalBefore));
    }

    receive() external payable {}
