pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 addAmount) internal {
        addAmount = bound(addAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= addAmount);
        uint balStart = address(this).balance;
        try c.addToBalance{value: addAmount}() {} catch { return; }
        uint256 userBalBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { userBalBefore = __r; } catch { return; }
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint balEnd = address(this).balance;
        assertTrue(balEnd + addAmount == balStart + (withdrawReverted ? 0 : userBalBefore));
    }

    function testFuzz_run(uint256 addAmount) public {
        _run(addAmount);
    }

    receive() external payable {}
}
